with d as (select value r from jsonb_array_elements($q$[{"slug":"kimchi-fried-rice","title":"Kimchi Fried Rice","cuisine":"korean","meal_types":["lunch","dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"kimchi-fried-rice","title":"Kimchi Fried Rice","summary":"Day-old rice fried hot with kimchi, bacon and gochujang, crowned with a fried egg.","cuisine":"korean","diets":["no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":15,"servings":2,"onePot":false,"ingredientGroups":[{"items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"streaky bacon","raw":"3 rashers streaky bacon, chopped","quantity":3,"unit":"rasher","ingredientId":"bacon","prep":"chopped"},{"item":"brown onion","raw":"1/2 brown onion, diced","quantity":0.5,"ingredientId":"brown-onion","prep":"diced"},{"item":"kimchi","raw":"200g kimchi, chopped, plus 3 tbsp of its juice","quantity":200,"unit":"g","ingredientId":"kimchi","prep":"chopped, plus 3 tbsp of its juice"},{"item":"gochujang","raw":"1 tbsp gochujang","quantity":1,"unit":"tbsp","ingredientId":"gochujang"},{"item":"cooked white rice","raw":"500g cooked white rice, cold from the fridge","quantity":500,"unit":"g","ingredientId":"white-rice","prep":"cold from the fridge"},{"item":"soy sauce","raw":"1 tsp soy sauce","quantity":1,"unit":"tsp","ingredientId":"soy-sauce"},{"item":"sesame oil","raw":"2 tsp sesame oil","quantity":2,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"eggs","raw":"2 eggs","quantity":2,"ingredientId":"egg"},{"item":"spring onions","raw":"2 spring onions, sliced","quantity":2,"ingredientId":"spring-onion","prep":"sliced"},{"item":"sesame seeds","raw":"1 tsp sesame seeds","quantity":1,"unit":"tsp","ingredientId":"sesame-seeds"},{"item":"nori","raw":"1 nori sheet, cut into thin strips (optional)","quantity":1,"unit":"sheet","ingredientId":"nori","prep":"cut into thin strips","optional":true}]}],"steps":[{"text":"Heat the oil in a large frying pan or wok over medium-high heat. Fry the bacon for 3 minutes until it starts to crisp. Add the onion and cook for 2 minutes."},{"text":"Add the kimchi and fry for 3 minutes, until it smells toasty. Stir in the gochujang."},{"text":"Add the rice and break up any clumps. Pour over the kimchi juice and soy sauce and toss for 4 to 5 minutes, until the rice is piping hot and starting to catch on the bottom. Stir through half the sesame oil."},{"text":"In a separate pan, fry the eggs in the rest of the sesame oil until the whites are set and the edges crisp."},{"text":"Divide the rice between bowls and top each with an egg, spring onion, sesame seeds and nori."}],"notes":["Use rice cooked the day before and cooled in the fridge. Freshly cooked rice steams and goes mushy, and cooked rice shouldn't sit out at room temperature.","Runny yolks aren't recommended for pregnant people, young children, older people or anyone with a weakened immune system. Fry the eggs until the yolks are firm.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"source":"user","provenance":"ai-draft"}},{"slug":"thai-pork-larb","title":"Thai Pork Larb","cuisine":"thai","meal_types":["lunch","dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"thai-pork-larb","title":"Thai Pork Larb","summary":"Warm pork mince tossed with lime, fish sauce, toasted rice and handfuls of fresh herbs.","cuisine":"thai","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Larb","items":[{"item":"jasmine rice","raw":"2 tbsp jasmine rice (uncooked, for toasting)","quantity":2,"unit":"tbsp","ingredientId":"jasmine-rice","note":"uncooked, for toasting"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"pork mince","raw":"500g pork mince","quantity":500,"unit":"g","ingredientId":"pork-mince"},{"item":"fish sauce","raw":"3 tbsp fish sauce","quantity":3,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"lime juice","raw":"60ml lime juice","quantity":60,"unit":"ml","ingredientId":"lime"},{"item":"brown sugar","raw":"1 tsp brown sugar","quantity":1,"unit":"tsp","ingredientId":"brown-sugar"},{"item":"chilli flakes","raw":"1/2-1 tsp chilli flakes","quantity":{"min":0.5,"max":1},"unit":"tsp","ingredientId":"chilli-flakes"},{"item":"shallots","raw":"3 shallots, thinly sliced","quantity":3,"ingredientId":"shallot","prep":"thinly sliced"},{"item":"spring onions","raw":"3 spring onions, sliced","quantity":3,"ingredientId":"spring-onion","prep":"sliced"},{"item":"mint leaves","raw":"1 cup mint leaves","quantity":1,"unit":"cup","ingredientId":"mint"},{"item":"coriander leaves","raw":"1 cup coriander leaves","quantity":1,"unit":"cup","ingredientId":"coriander"}]},{"title":"To serve","items":[{"item":"baby cos lettuce","raw":"1 baby cos lettuce, leaves separated","quantity":1,"ingredientId":"cos-lettuce","prep":"leaves separated"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, sliced","quantity":1,"ingredientId":"cucumber","prep":"sliced"},{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"},{"item":"Lime wedges","raw":"Lime wedges","ingredientId":"lime"}]}],"steps":[{"text":"Toast the 2 tbsp rice in a dry frying pan over medium heat for 6 to 8 minutes, shaking the pan, until deep golden. Cool, then grind to a coarse powder in a mortar and pestle or spice grinder."},{"text":"Heat the oil in the same pan over medium-high heat. Add the pork and cook for 6 to 7 minutes, breaking it up, until cooked through with no pink left."},{"text":"Take the pan off the heat. Stir in the fish sauce, lime juice, sugar and chilli flakes. Taste: it should be sour, salty and hot in about equal measure."},{"text":"Fold in the shallot, spring onion, most of the herbs and half the toasted rice powder."},{"text":"Pile onto a plate and scatter with the remaining herbs and rice powder. Serve warm with lettuce cups, cucumber, rice and lime wedges."}],"notes":["The toasted rice powder gives larb its nutty crunch. Make extra and keep it in a jar for a month.","Chicken mince works the same way; cook it until it's white all the way through.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"sausage-rolls","title":"Sausage Rolls","cuisine":"modern-australian","meal_types":["snack","lunch"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":60,"recipe":{"id":"sausage-rolls","title":"Sausage Rolls","summary":"Flaky homemade sausage rolls with a herby pork and vegetable filling and a sesame top.","cuisine":"modern-australian","diets":["no-dairy"],"mealTypes":["snack","lunch"],"difficulty":"medium","prepMinutes":30,"cookMinutes":30,"servings":6,"onePot":false,"ingredientGroups":[{"title":"Filling","items":[{"item":"pork mince","raw":"500g pork mince","quantity":500,"unit":"g","ingredientId":"pork-mince"},{"item":"brown onion","raw":"1 brown onion, finely grated","quantity":1,"ingredientId":"brown-onion","prep":"finely grated"},{"item":"carrot","raw":"1 carrot, finely grated","quantity":1,"ingredientId":"carrot","prep":"finely grated"},{"item":"zucchini","raw":"1 zucchini, finely grated and squeezed dry","quantity":1,"ingredientId":"zucchini","prep":"finely grated and squeezed dry"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"dried breadcrumbs","raw":"40g dried breadcrumbs","quantity":40,"unit":"g","ingredientId":"breadcrumbs"},{"item":"egg","raw":"1 egg","quantity":1,"ingredientId":"egg"},{"item":"fennel seeds","raw":"1 tsp fennel seeds, lightly crushed","quantity":1,"unit":"tsp","ingredientId":"fennel-seeds","prep":"lightly crushed"},{"item":"thyme leaves","raw":"1 tbsp thyme leaves","quantity":1,"unit":"tbsp","ingredientId":"thyme"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"Pastry","items":[{"item":"frozen puff pastry","raw":"3 sheets frozen puff pastry, just thawed","quantity":3,"unit":"sheet","ingredientId":"puff-pastry","prep":"just thawed"},{"item":"egg","raw":"1 egg, beaten, for brushing","quantity":1,"ingredientId":"egg","prep":"beaten, for brushing"},{"item":"sesame seeds","raw":"2 tsp sesame seeds","quantity":2,"unit":"tsp","ingredientId":"sesame-seeds"}]},{"title":"To serve","items":[{"item":"Tomato sauce","raw":"Tomato sauce","ingredientId":"tomato-sauce"}]}],"steps":[{"text":"Heat the oven to 210°C (190°C fan-forced) and line two trays with baking paper."},{"text":"Mix all the filling ingredients in a bowl with your hands until well combined."},{"text":"Cut each pastry sheet in half to make six rectangles. Spoon a sixth of the filling along one long edge of each, shaping it into a log. Brush the far edge with beaten egg and roll up so the join sits underneath."},{"text":"Cut each log into four rolls and place on the trays, join side down. Brush the tops with egg, sprinkle with sesame seeds and cut two small slashes in each."},{"text":"Bake for 25 to 30 minutes, until the pastry is puffed and deep golden and the filling is cooked through (75°C in the centre). Cool for 5 minutes and serve with tomato sauce."}],"notes":["Keep the pastry cold: if it goes soft and sticky while you work, put it back in the fridge for 10 minutes.","Freeze unbaked rolls on a tray, then bag them. Bake from frozen at the same temperature, allowing 10 minutes more.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"thai-fish-cakes","title":"Thai Fish Cakes","cuisine":"thai","meal_types":["snack","dinner"],"diets":["pescatarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"thai-fish-cakes","title":"Thai Fish Cakes","summary":"Bouncy red curry fish cakes with green beans and lime leaf, and a quick cucumber relish.","cuisine":"thai","diets":["pescatarian","no-gluten","no-dairy"],"mealTypes":["snack","dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Fish cakes","items":[{"item":"firm white fish fillets","raw":"500g firm white fish fillets, skinned, boned and chopped","quantity":500,"unit":"g","ingredientId":"white-fish","prep":"skinned, boned and chopped"},{"item":"red curry paste","raw":"2 tbsp red curry paste","quantity":2,"unit":"tbsp","ingredientId":"red-curry-paste"},{"item":"egg","raw":"1 egg","quantity":1,"ingredientId":"egg"},{"item":"fish sauce","raw":"1 tbsp fish sauce","quantity":1,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"},{"item":"makrut lime","raw":"4 makrut lime leaves, very finely shredded","quantity":4,"unit":"leaf","ingredientId":"makrut-lime-leaf","prep":"very finely shredded"},{"item":"green beans","raw":"100g green beans, very thinly sliced","quantity":100,"unit":"g","ingredientId":"green-beans","prep":"very thinly sliced"},{"item":"neutral oil","raw":"80ml neutral oil, for frying","quantity":80,"unit":"ml","ingredientId":"neutral-oil","prep":"for frying"}]},{"title":"Cucumber relish","items":[{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, finely diced","quantity":1,"ingredientId":"cucumber","prep":"finely diced"},{"item":"shallot","raw":"1 shallot, finely sliced","quantity":1,"ingredientId":"shallot","prep":"finely sliced"},{"item":"long red chilli","raw":"1 long red chilli, finely sliced","quantity":1,"ingredientId":"red-chilli","prep":"finely sliced"},{"item":"rice vinegar","raw":"60ml rice vinegar","quantity":60,"unit":"ml","ingredientId":"rice-vinegar"},{"item":"sugar","raw":"2 tbsp sugar","quantity":2,"unit":"tbsp","ingredientId":"sugar"},{"item":"crushed roasted peanuts","raw":"1 tbsp crushed roasted peanuts","quantity":1,"unit":"tbsp","ingredientId":"peanuts"}]},{"title":"To serve","items":[{"item":"Sweet chilli sauce","raw":"Sweet chilli sauce","ingredientId":"sweet-chilli-sauce"},{"item":"Lime wedges","raw":"Lime wedges","ingredientId":"lime"}]}],"steps":[{"text":"For the relish, warm the vinegar and sugar in a small pan until the sugar dissolves. Cool, then pour over the cucumber, shallot and chilli. Top with peanuts just before serving."},{"text":"Blitz the fish, curry paste, egg, fish sauce and sugar in a food processor to a smooth, sticky paste, about 1 minute."},{"text":"Tip into a bowl and mix in the lime leaves and green beans. With wet hands, shape into 16 small patties about 1.5cm thick."},{"text":"Heat the oil in a large frying pan over medium heat. Fry the fish cakes in batches for 2 to 3 minutes each side, until golden, puffed and cooked through. Drain on paper towel."},{"text":"Serve hot with the cucumber relish, sweet chilli sauce and lime wedges."}],"notes":["Most Thai red curry pastes contain shrimp paste. Check the label if you're cooking for someone who avoids shellfish.","Ling, flathead or barramundi all work well. Avoid oily fish here.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"source":"user","provenance":"ai-draft"}},{"slug":"potato-pancakes","title":"Potato Pancakes","cuisine":"central-european","meal_types":["snack","breakfast","lunch"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"potato-pancakes","title":"Potato Pancakes","summary":"Lacy, crisp-edged grated potato pancakes with apple sauce and sour cream.","cuisine":"central-european","diets":["vegetarian"],"mealTypes":["snack","breakfast","lunch"],"difficulty":"easy","prepMinutes":20,"cookMinutes":30,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Pancakes","items":[{"item":"floury potatoes","raw":"1kg floury potatoes, peeled","quantity":1,"unit":"kg","ingredientId":"potato","prep":"peeled"},{"item":"brown onion","raw":"1 brown onion","quantity":1,"ingredientId":"brown-onion"},{"item":"eggs","raw":"2 eggs","quantity":2,"ingredientId":"egg"},{"item":"plain flour","raw":"3 tbsp plain flour","quantity":3,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"nutmeg","raw":"Pinch of nutmeg","quantity":1,"unit":"pinch","ingredientId":"nutmeg"},{"item":"neutral oil","raw":"125ml neutral oil, for frying","quantity":125,"unit":"ml","ingredientId":"neutral-oil","prep":"for frying"}]},{"title":"To serve","items":[{"item":"apple sauce","raw":"200g apple sauce","quantity":200,"unit":"g","ingredientId":"apple-sauce"},{"item":"sour cream","raw":"150g sour cream","quantity":150,"unit":"g","ingredientId":"sour-cream"},{"item":"chives","raw":"1 tbsp chives, chopped","quantity":1,"unit":"tbsp","ingredientId":"chives","prep":"chopped"}]}],"steps":[{"text":"Heat the oven to 100°C (80°C fan-forced) to keep the pancakes warm as you cook them."},{"text":"Coarsely grate the potatoes and onion into a clean tea towel. Gather it up and twist hard over the sink to squeeze out as much liquid as you can. Dry potato is the secret to crisp pancakes."},{"text":"Tip into a bowl and mix in the eggs, flour, salt and nutmeg."},{"text":"Heat a 5mm layer of oil in a large frying pan over medium-high heat. Drop in heaped tablespoons of the mixture and flatten to about 1cm. Fry for 3 to 4 minutes each side, until deep golden and crisp and cooked through in the middle."},{"text":"Drain on paper towel and keep warm in the oven while you cook the rest, adding more oil as needed. Serve hot with apple sauce, sour cream and chives."}],"notes":["Grate the potatoes just before cooking; they turn grey if they sit.","Smoked salmon and a dollop of sour cream turns these into a weekend brunch."],"source":"user","provenance":"ai-draft"}},{"slug":"suya-beef-skewers","title":"Suya Beef Skewers","cuisine":"west-african","meal_types":["dinner","snack"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":60,"recipe":{"id":"suya-beef-skewers","title":"Suya Beef Skewers","summary":"Nigerian street-food beef skewers in a smoky, spicy peanut rub, with raw onion and tomato.","cuisine":"west-african","diets":["no-gluten","no-dairy"],"mealTypes":["dinner","snack"],"difficulty":"easy","prepMinutes":50,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Suya spice","items":[{"item":"roasted peanuts","raw":"70g roasted peanuts","quantity":70,"unit":"g","ingredientId":"peanuts"},{"item":"smoked paprika","raw":"2 tsp smoked paprika","quantity":2,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"ground ginger","raw":"1 tsp ground ginger","quantity":1,"unit":"tsp","ingredientId":"ground-ginger"},{"item":"garlic powder","raw":"1 tsp garlic powder","quantity":1,"unit":"tsp","ingredientId":"garlic-powder"},{"item":"onion powder","raw":"1 tsp onion powder","quantity":1,"unit":"tsp","ingredientId":"onion-powder"},{"item":"cayenne pepper","raw":"1/2-1 tsp cayenne pepper","quantity":{"min":0.5,"max":1},"unit":"tsp","ingredientId":"cayenne"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"Beef","items":[{"item":"beef rump steak","raw":"700g beef rump steak, cut into 2cm thick strips","quantity":700,"unit":"g","ingredientId":"beef-rump","prep":"cut into 2cm thick strips"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"To serve","items":[{"item":"red onion","raw":"1 red onion, thinly sliced","quantity":1,"ingredientId":"red-onion","prep":"thinly sliced"},{"item":"tomatoes","raw":"2 tomatoes, sliced","quantity":2,"ingredientId":"tomato","prep":"sliced"},{"item":"Lebanese cucumber","raw":"1 Lebanese cucumber, sliced","quantity":1,"ingredientId":"cucumber","prep":"sliced"},{"item":"Lime wedges","raw":"Lime wedges","ingredientId":"lime"}]}],"steps":[{"text":"Soak 12 bamboo skewers in water for 30 minutes so they don't burn."},{"text":"Grind the peanuts in a food processor or spice grinder to a fine, dry powder; stop before it turns to butter. Mix with the paprika, ginger, garlic and onion powders, cayenne and salt."},{"text":"Toss the beef with the oil, then with two thirds of the spice mix until well coated. Thread onto the skewers and leave for 15 minutes."},{"text":"Heat a barbecue grill or chargrill pan over high heat. Cook the skewers for 3 to 4 minutes each side, until charred at the edges and done to your liking."},{"text":"Scatter the skewers with the rest of the spice mix and serve with the onion, tomato, cucumber and lime."}],"notes":["Contains peanuts. The spice mix keeps for a month in a jar and is excellent on chicken thighs.","Suya is meant to be hot. Start with 1/2 tsp cayenne if you're feeding children.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-cacciatore","title":"Chicken Cacciatore","cuisine":"italian","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":75,"recipe":{"id":"chicken-cacciatore","title":"Chicken Cacciatore","summary":"Chicken thighs braised with capsicum, mushroom, rosemary, red wine and tomato.","cuisine":"italian","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":60,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"bone-in skin-on chicken thighs","raw":"8 bone-in skin-on chicken thighs (about 1.4kg)","quantity":8,"ingredientId":"chicken-thigh-bone-in","note":"about 1.4kg"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, sliced","quantity":1,"ingredientId":"brown-onion","prep":"sliced"},{"item":"red capsicum","raw":"1 red capsicum, sliced","quantity":1,"ingredientId":"capsicum","prep":"sliced"},{"item":"button mushrooms","raw":"200g button mushrooms, quartered","quantity":200,"unit":"g","ingredientId":"button-mushroom","prep":"quartered"},{"item":"garlic","raw":"4 garlic cloves, sliced","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"rosemary","raw":"2 rosemary sprigs","quantity":2,"unit":"sprig","ingredientId":"rosemary"},{"item":"red wine","raw":"125ml red wine","quantity":125,"unit":"ml","ingredientId":"red-wine"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"chicken stock","raw":"125ml chicken stock","quantity":125,"unit":"ml","ingredientId":"chicken-stock"},{"item":"kalamata olives","raw":"60g kalamata olives","quantity":60,"unit":"g","ingredientId":"kalamata-olive"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"},{"item":"Crusty bread","raw":"Crusty bread, to serve (optional)","ingredientId":"crusty-bread","prep":"to serve","optional":true}]}],"steps":[{"text":"Pat the chicken dry and season with the salt. Heat the oil in a large heavy pan or casserole over medium-high heat. Brown the chicken skin side down for 6 to 8 minutes until deep golden, turn for 2 minutes, then lift onto a plate."},{"text":"Pour off all but 2 tbsp of the fat. Add the onion, capsicum and mushrooms and cook for 8 minutes until soft and lightly browned. Add the garlic and rosemary for 1 minute."},{"text":"Pour in the wine and simmer for 2 minutes, scraping up the browned bits. Add the tomatoes and stock and bring to a simmer."},{"text":"Return the chicken, skin side up, so the skin sits above the sauce. Cover and simmer gently for 30 minutes, then uncover and cook for 10 minutes more, until the sauce has thickened and the chicken is cooked through (75°C next to the bone)."},{"text":"Stir the olives into the sauce, scatter with parsley and serve with crusty bread, mash or polenta."}],"notes":["Better the next day. Cool, refrigerate, and reheat gently until piping hot.","No wine? Use extra stock and a teaspoon of red wine vinegar.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"salmon-en-papillote","title":"Salmon en Papillote","cuisine":"french","meal_types":["dinner"],"diets":["pescatarian","no-gluten"],"difficulty":"easy","total_minutes":45,"recipe":{"id":"salmon-en-papillote","title":"Salmon en Papillote","summary":"Salmon steamed in paper parcels with zucchini, tomato, lemon, dill and a little butter.","cuisine":"french","diets":["pescatarian","no-gluten"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":25,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Potatoes","items":[{"item":"baby potatoes","raw":"600g baby potatoes, halved","quantity":600,"unit":"g","ingredientId":"waxy-potato","prep":"halved"},{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"Salt and pepper","raw":"Salt and pepper","ingredientId":"salt"}]},{"title":"Parcels","items":[{"item":"skinless salmon","raw":"4 skinless salmon fillets (about 160g each)","quantity":4,"unit":"fillet","ingredientId":"salmon","note":"about 160g each"},{"item":"zucchini","raw":"2 zucchini, cut into thin ribbons with a peeler","quantity":2,"ingredientId":"zucchini","prep":"cut into thin ribbons with a peeler"},{"item":"cherry tomatoes","raw":"200g cherry tomatoes, halved","quantity":200,"unit":"g","ingredientId":"cherry-tomato","prep":"halved"},{"item":"lemon","raw":"1 lemon, thinly sliced","quantity":1,"ingredientId":"lemon","prep":"thinly sliced"},{"item":"capers","raw":"1 tbsp capers, rinsed","quantity":1,"unit":"tbsp","ingredientId":"capers","prep":"rinsed"},{"item":"butter","raw":"40g butter, cut into 4","quantity":40,"unit":"g","ingredientId":"butter","prep":"cut into 4"},{"item":"dry white wine","raw":"60ml dry white wine","quantity":60,"unit":"ml","ingredientId":"white-wine"},{"item":"dill","raw":"4 dill sprigs","quantity":4,"unit":"sprig","ingredientId":"dill"},{"item":"Salt and pepper","raw":"Salt and pepper","ingredientId":"salt"}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced). Toss the potatoes with the oil, salt and pepper on a tray and roast for 25 minutes, until golden and tender."},{"text":"While they roast, cut four 40cm squares of baking paper. Pile a quarter of the zucchini in the middle of each, top with a salmon fillet and season."},{"text":"Lay the lemon slices, tomatoes and capers over the salmon. Add a piece of butter, a dill sprig and a tablespoon of wine to each."},{"text":"Bring the long sides of the paper together and fold over tightly several times, then twist the ends like a lolly wrapper. Put the parcels on a tray."},{"text":"When the potatoes have 12 minutes left, bake the parcels on the shelf below for 12 minutes, until the salmon is just opaque in the centre. Open one to check; it should flake easily."},{"text":"Put a parcel on each plate for everyone to open at the table (watch the steam). The paper should be puffed and lightly golden, and the salmon opaque and flaking easily, with the potatoes alongside."}],"notes":["Thicker fillets may need 2 to 3 minutes more. The fish keeps cooking in the parcel once it's out of the oven.","Barramundi or snapper fillets work the same way.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"lentils-and-sausages","title":"Lentils with Sausages","cuisine":"french","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":65,"recipe":{"id":"lentils-and-sausages","title":"Lentils with Sausages","summary":"French-style braised Puy lentils with browned pork sausages, thyme and a mustardy finish.","cuisine":"french","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":50,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"thick pork sausages","raw":"8 thick pork sausages","quantity":8,"ingredientId":"pork-sausage"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"carrot","raw":"1 carrot, finely diced","quantity":1,"ingredientId":"carrot","prep":"finely diced"},{"item":"celery","raw":"1 celery stalk, finely diced","quantity":1,"unit":"stalk","ingredientId":"celery","prep":"finely diced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"thyme","raw":"4 thyme sprigs","quantity":4,"unit":"sprig","ingredientId":"thyme"},{"item":"bay","raw":"2 bay leaves","quantity":2,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"puy lentils","raw":"300g puy lentils, rinsed","quantity":300,"unit":"g","ingredientId":"brown-lentils","prep":"rinsed"},{"item":"dry white wine","raw":"125ml dry white wine","quantity":125,"unit":"ml","ingredientId":"white-wine"},{"item":"chicken stock","raw":"750ml chicken stock","quantity":750,"unit":"ml","ingredientId":"chicken-stock"},{"item":"Dijon mustard","raw":"1 tbsp Dijon mustard","quantity":1,"unit":"tbsp","ingredientId":"dijon-mustard"},{"item":"red wine vinegar","raw":"1 tbsp red wine vinegar","quantity":1,"unit":"tbsp","ingredientId":"red-wine-vinegar"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"},{"item":"Salt and pepper","raw":"Salt and pepper","ingredientId":"salt"}]}],"steps":[{"text":"Heat the oil in a large deep frying pan or casserole over medium heat. Brown the sausages all over for 8 minutes, then lift onto a plate. They'll finish cooking in the lentils."},{"text":"Add the onion, carrot and celery to the pan and cook for 8 minutes until soft. Add the garlic, thyme and bay for 1 minute."},{"text":"Stir in the lentils, then the wine, and let it bubble for 1 minute. Pour in the stock and bring to a simmer."},{"text":"Nestle the sausages into the lentils. Cover and simmer gently for 25 to 30 minutes, stirring now and then, until the lentils are tender but still hold their shape and the sausages are cooked through (75°C in the centre). Add a splash of water if it dries out."},{"text":"Remove the thyme stalks and bay. Stir in the mustard and vinegar, season, and scatter with parsley."}],"notes":["Puy (French green) lentils hold their shape. Brown lentils work but go softer, so check them after 20 minutes.","Check the sausage label if you need this gluten-free; many sausages contain wheat.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"source":"user","provenance":"ai-draft"}},{"slug":"chorizo-chickpea-stew","title":"Chorizo and Chickpea Stew","cuisine":"spanish","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"chorizo-chickpea-stew","title":"Chorizo and Chickpea Stew","summary":"Smoky Spanish chorizo, chickpeas and spinach in a paprika tomato broth, ready in 30 minutes.","cuisine":"spanish","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":25,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"chorizo sausages","raw":"2 chorizo sausages (about 250g), sliced into rounds","quantity":2,"ingredientId":"chorizo","prep":"sliced into rounds","note":"about 250g"},{"item":"brown onion","raw":"1 brown onion, diced","quantity":1,"ingredientId":"brown-onion","prep":"diced"},{"item":"red capsicum","raw":"1 red capsicum, diced","quantity":1,"ingredientId":"capsicum","prep":"diced"},{"item":"garlic","raw":"3 garlic cloves, sliced","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"smoked paprika","raw":"2 tsp smoked paprika","quantity":2,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"tinned chickpeas","raw":"800g tinned chickpeas, drained and rinsed","quantity":800,"unit":"g","ingredientId":"chickpeas","prep":"drained and rinsed"},{"item":"chicken stock","raw":"375ml chicken stock","quantity":375,"unit":"ml","ingredientId":"chicken-stock"},{"item":"baby spinach","raw":"100g baby spinach","quantity":100,"unit":"g","ingredientId":"baby-spinach"},{"item":"sherry vinegar","raw":"1 tbsp sherry vinegar","quantity":1,"unit":"tbsp","ingredientId":"sherry-vinegar"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"},{"item":"Crusty bread","raw":"Crusty bread, to serve (optional)","ingredientId":"crusty-bread","prep":"to serve","optional":true}]}],"steps":[{"text":"Heat the oil in a large deep frying pan over medium heat. Fry the chorizo for 4 to 5 minutes, until crisp at the edges and the pan is full of red oil. Lift out with a slotted spoon."},{"text":"Cook the onion and capsicum in the chorizo oil for 7 minutes until soft. Add the garlic and paprika and stir for 1 minute."},{"text":"Add the tomatoes, chickpeas and stock. Simmer for 12 minutes, until slightly thickened. Crush some of the chickpeas against the side of the pan to thicken it further."},{"text":"Return the chorizo, stir in the spinach until wilted, then add the vinegar. Taste for salt; the chorizo is salty, so you may not need any."},{"text":"Scatter with parsley and serve with crusty bread for the sauce."}],"notes":["Use cured Spanish chorizo, the firm kind sold near the salami, not fresh chorizo.","Top with a fried egg for a weekend breakfast."],"source":"user","provenance":"ai-draft"}},{"slug":"greek-lemon-chicken-potatoes","title":"Greek Lemon Chicken and Potatoes","cuisine":"greek","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":75,"recipe":{"id":"greek-lemon-chicken-potatoes","title":"Greek Lemon Chicken and Potatoes","summary":"A one-tray roast of chicken thighs and potatoes soaked in lemon, garlic and oregano.","cuisine":"greek","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":60,"servings":4,"onePot":true,"ingredientGroups":[{"items":[{"item":"bone-in skin-on chicken thighs","raw":"8 bone-in skin-on chicken thighs (about 1.4kg)","quantity":8,"ingredientId":"chicken-thigh-bone-in","note":"about 1.4kg"},{"item":"potatoes","raw":"1kg potatoes, peeled and cut into thick wedges","quantity":1,"unit":"kg","ingredientId":"potato","prep":"peeled and cut into thick wedges"},{"item":"olive oil","raw":"80ml olive oil","quantity":80,"unit":"ml","ingredientId":"olive-oil"},{"item":"lemons","raw":"Juice of 2 lemons","quantity":2,"ingredientId":"lemon","prep":"juiced"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"},{"item":"garlic","raw":"6 garlic cloves, crushed","quantity":6,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"dried oregano","raw":"1 tbsp dried oregano","quantity":1,"unit":"tbsp","ingredientId":"dried-oregano"},{"item":"chicken stock","raw":"250ml chicken stock","quantity":250,"unit":"ml","ingredientId":"chicken-stock"},{"item":"salt","raw":"1 1/2 tsp salt","quantity":1.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"}]},{"title":"To serve","items":[{"item":"Green salad","raw":"Green salad","ingredientId":"salad-leaves"}]}],"steps":[{"text":"Heat the oven to 220°C (200°C fan-forced)."},{"text":"In a large roasting tin, toss the potatoes with half the oil, half the lemon juice, half the garlic, half the oregano and half the salt and pepper. Spread out in a single layer."},{"text":"Rub the chicken with the rest of the oil, lemon juice, garlic, oregano, salt and pepper. Sit it skin side up among the potatoes and tuck in the lemon wedges. Pour the stock around the potatoes, not over the chicken."},{"text":"Roast for 50 to 60 minutes, turning the potatoes once halfway, until the chicken skin is crisp and golden, the potatoes are tender and have soaked up the juices, and the chicken is cooked through (75°C next to the bone). If the tray dries out, add a splash of water."},{"text":"Scatter with parsley and serve with a green salad, spooning the pan juices over everything."}],"notes":["Don't crowd the tray. Use two if you need to, or the potatoes steam instead of roasting.","Check the stock label if you need this gluten-free.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"prawn-saganaki","title":"Prawn Saganaki","cuisine":"greek","meal_types":["dinner"],"diets":["pescatarian","no-gluten"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"prawn-saganaki","title":"Prawn Saganaki","summary":"Prawns baked in a garlicky tomato and white wine sauce under crumbled, melting feta.","cuisine":"greek","diets":["pescatarian","no-gluten"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":25,"servings":4,"onePot":true,"seasons":["spring","summer"],"ingredientGroups":[{"items":[{"item":"raw king prawns","raw":"800g raw king prawns, peeled and deveined, tails on","quantity":800,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined, tails on"},{"item":"olive oil","raw":"3 tbsp olive oil","quantity":3,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"garlic","raw":"4 garlic cloves, sliced","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"sliced"},{"item":"chilli flakes","raw":"1/2 tsp chilli flakes","quantity":0.5,"unit":"tsp","ingredientId":"chilli-flakes"},{"item":"dry white wine","raw":"125ml dry white wine","quantity":125,"unit":"ml","ingredientId":"white-wine"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"dried oregano","raw":"1 tsp dried oregano","quantity":1,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"sugar","raw":"1/2 tsp sugar","quantity":0.5,"unit":"tsp","ingredientId":"sugar"},{"item":"feta","raw":"150g feta, crumbled","quantity":150,"unit":"g","ingredientId":"feta","prep":"crumbled"},{"item":"dill","raw":"2 tbsp dill, chopped","quantity":2,"unit":"tbsp","ingredientId":"dill","prep":"chopped"},{"item":"Salt and pepper","raw":"Salt and pepper","ingredientId":"salt"},{"item":"Crusty bread","raw":"Crusty bread, to serve (optional)","ingredientId":"crusty-bread","prep":"to serve","optional":true}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced)."},{"text":"Heat the oil in a large ovenproof frying pan over medium heat. Cook the onion for 6 minutes until soft. Add the garlic and chilli flakes for 1 minute."},{"text":"Pour in the wine and let it bubble for 2 minutes. Add the tomatoes, oregano and sugar and simmer for 8 minutes, until thick. Season."},{"text":"Take the pan off the heat. Nestle the prawns into the sauce in a single layer and scatter over the feta."},{"text":"Bake for 8 to 10 minutes, until the prawns are pink and firm all the way through and the feta has softened and caught at the edges."},{"text":"Scatter with dill and serve straight from the pan, with crusty bread for the sauce."}],"notes":["Don't overcook the prawns. They're done as soon as they curl into a loose C and turn opaque.","No ovenproof pan? Pour the sauce into a baking dish before adding the prawns.","Food safety: Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;